"""Detect machine-generated source files from their path and content.

Ported from codegraph's ``src/extraction/generated-detection.ts``. A file is
generated when any of three signals fires:

1. Its filename follows a code generator's convention (``_pb2.py``,
   ``.pb.go``, ``.g.cs``, ...).
2. Its head carries a generator banner on a comment line (the conventions
   are listed in _GENERATED_BANNERS). Go's convention is content-only, so a
   generated ``payroll.go`` is invisible to (1).
3. It is a JavaScript file that a bundler or minifier wrote as a few enormous
   lines.

The banner list is precision-first: a false positive drops hand-written code
from the hub and entry-point rankings. Generated files are flagged, not
skipped, so imports of them still resolve to graph edges.

The banner patterns sit below HEADER_SCAN_LINES of this file on purpose, so
the module does not classify itself when codemapy maps its own source.
"""

from __future__ import annotations

import re

HEADER_SCAN_CHARS = 8192
HEADER_SCAN_LINES = 60

# A line this long is not written by hand.
MINIFIED_LINE_CHARS = 1000
MINIFIED_MIN_CHARS = 4 * MINIFIED_LINE_CHARS
MINIFIED_LONG_TEXT_SHARE = 0.5
MINIFIED_PUNCTUATION_SHARE = 0.03
MINIFIED_PUNCTUATION = frozenset(";{}(),")

_MINIFIABLE_SCRIPT = re.compile(r"\.(?:m?js|cjs)$", re.IGNORECASE)
_WEBPACK_RUNTIME = re.compile(r"\bfunction __webpack_require__\s*\(")

# Every banner below contains this stem, so one scan rejects nearly all
# hand-written files before any line splitting.
_GENERATED_STEM = re.compile(r"generat", re.IGNORECASE)

# Line-comment leaders across the languages codemapy maps. A banner must sit
# on a comment line (or inside an open block comment) so a generator's own
# source, which holds the banner as a string constant, is not flagged.
_COMMENT_LEADER = re.compile(
    r"^\s*(?://|/\*+|\*+/?|#+|--+|<!--|%+|;+|'|!|\(\*|\{-|\"\"\"|'''|=begin|<#|@rem\b|rem\b)",
    re.IGNORECASE,
)

# Block comments, per language. Tracking them all everywhere misreads embedded
# code: a JS test holding Python source in a template string opened a `"""`
# "comment" and its expected-output docstring passed for a banner.
_C_BLOCK = ("/*", "*/")
_BLOCK_DELIMITERS_BY_SUFFIX: dict[str, tuple[tuple[str, str], ...]] = {
    ".py": (('"""', '"""'), ("'''", "'''")),
    ".rb": (("=begin", "=end"),),
    ".lua": (("--[[", "]]"),),
    ".svelte": (_C_BLOCK, ("<!--", "-->")),
    ".sh": (),
    ".bash": (),
    ".zsh": (),
}
_DEFAULT_BLOCK_DELIMITERS = (_C_BLOCK,)

_GENERATED_PATH_PATTERNS = tuple(
    re.compile(pattern)
    for pattern in (
        # Go: protobuf, gRPC, pulsar, mockgen.
        r"\.pb\.go$",
        r"\.pulsar\.go$",
        r"_grpc\.pb\.go$",
        r"_mocks?\.go$",
        r"(?:^|/)mock_[^/]+\.go$",
        # JavaScript / TypeScript codegen (GraphQL, Prisma, ts-proto, gRPC-web).
        r"\.generated\.[jt]sx?$",
        r"\.gen\.[jt]sx?$",
        r"\.pb\.[jt]s$",
        r"_pb\.[jt]s$",
        r"_grpc_pb\.[jt]s$",
        r"[.-]min\.m?js$",
        # Python: protobuf / gRPC.
        r"_pb2(?:_grpc)?\.py$",
        r"_pb2\.pyi$",
        # C++: protobuf.
        r"\.pb\.(?:cc|h)$",
        # C#: protobuf / gRPC, designer and source-generator output.
        r"\.g\.cs$",
        r"Grpc\.cs$",
        # Java: protobuf / gRPC.
        r"OuterClass\.java$",
        r"Grpc\.java$",
        # Swift: protobuf.
        r"\.pb\.swift$",
        # Rust: in-tree build output.
        r"\.generated\.rs$",
    )
)

_GENERATED_BANNERS = tuple(
    re.compile(pattern, re.IGNORECASE)
    for pattern in (
        # Go's codified convention, also used by sqlc, ent, wire, stringer.
        r"\bcode generated\b.{0,200}?\bdo not edit\b",
        # protoc, ANTLR, FlatBuffers, bindgen: "Generated by ... DO NOT EDIT".
        r"\b(?:automatically |auto[- ]?)?generated (?:by|from|with)\b.{0,200}?\bdo not (?:edit|modify|change)\b",
        # The standalone `@generated` tag (Relay, GraphQL codegen, Meta).
        r"(?:^|[^\w@])@generated\b",
        # .NET's `<auto-generated>` doc tag.
        r"<auto-?generated\s*/?>",
        # swagger-codegen, Thrift: "auto generated by"; "by" is required.
        r"\b(?:automatically generated|auto[- ]?generated|autogenerated) by\b",
        # "Generated by <tool> by running `<command>`".
        r"\bgenerated by\s+\S.{0,80}?\bby running\b",
        # Self-declaring in-house banners.
        r"\bthis (?:file|class|code|module) (?:is|was) (?:auto[- ]?)?generated\b",
        # "DO NOT EDIT -- this is a generated file".
        r"\bdo not (?:edit|modify)\b.{0,120}?\b(?:auto[- ]?generated|generated file|generated code)\b",
    )
)

# A banner naming a one-time scaffolding step ("generated by the Gradle 'init'
# task", "generated by the `rspec --init` command", "generated by the `rails
# generate rspec:install` command") marks a template that the project then
# owns and edits, not regenerated output.
_SCAFFOLD_NOTE = re.compile(
    r"\b(?:init|install|new|startproject|startapp|scaffold)\b.{0,20}?\b(?:task|command)\b|--init\b",
    re.IGNORECASE,
)


def is_generated_source(rel_path: str, content: str) -> bool:
    """Return True if the file at *rel_path* with *content* is machine-generated."""
    return (
        has_generated_path(rel_path)
        or has_generated_header(content, rel_path)
        or is_minified_script(rel_path, content)
    )


def has_generated_path(rel_path: str) -> bool:
    """True if *rel_path* (POSIX, project-relative) follows a codegen naming convention."""
    return any(pattern.search(rel_path) for pattern in _GENERATED_PATH_PATTERNS)


def has_generated_header(content: str, rel_path: str = "") -> bool:
    """True if the head of *content* carries a generator banner on a comment line.

    *rel_path* selects which block-comment delimiters to track; without it,
    only ``/* ... */`` blocks are.
    """
    head = content[:HEADER_SCAN_CHARS]
    if not _GENERATED_STEM.search(head):
        return False

    suffix = rel_path[rel_path.rfind(".") :].lower() if "." in rel_path else ""
    delimiters = _BLOCK_DELIMITERS_BY_SUFFIX.get(suffix, _DEFAULT_BLOCK_DELIMITERS)
    open_block: tuple[str, str] | None = None
    for line in head.split("\n")[:HEADER_SCAN_LINES]:
        if open_block is not None or _COMMENT_LEADER.match(line):
            if any(banner.search(line) for banner in _GENERATED_BANNERS) and not _SCAFFOLD_NOTE.search(line):
                return True
        # Advance the block state after testing, so the opening line of a
        # `/* Code generated ... */` block is itself matched by the leader rule.
        if open_block is not None:
            if open_block[1] in line:
                open_block = None
            continue
        for opener, closer in delimiters:
            at = line.find(opener)
            if at < 0:
                continue
            if line.find(closer, at + len(opener)) < 0:
                open_block = (opener, closer)
            break
    return False


def is_minified_script(rel_path: str, content: str) -> bool:
    """True if a JavaScript file is a bundle or minified build.

    Either it carries webpack's module loader, or at least half its text sits
    on lines of MINIFIED_LINE_CHARS or more that are dense with ``;{}(),``
    (which rules out one long string literal in an ordinary file).
    """
    if not _MINIFIABLE_SCRIPT.search(rel_path) or len(content) < MINIFIED_MIN_CHARS:
        return False
    if _WEBPACK_RUNTIME.search(content):
        return True
    long_chars = 0
    punctuation = 0
    for line in content.split("\n"):
        if len(line) >= MINIFIED_LINE_CHARS:
            long_chars += len(line)
            punctuation += sum(1 for char in line if char in MINIFIED_PUNCTUATION)
    return (
        long_chars >= len(content) * MINIFIED_LONG_TEXT_SHARE
        and punctuation >= long_chars * MINIFIED_PUNCTUATION_SHARE
    )
